exec((__import__('pathlib').Path(__file__).parent/'build-home.py').read_text())

write(Path('sections/header.liquid'),section('Performance Meals header',r'''
{% liquid
  assign brand = 'pm'
  assign brand_label = 'brands.performance_meals' | t
  assign brand_color = '#F5B300'
  if request.path contains 'meal-plan'
    assign brand = 'mp'
    assign brand_label = 'brands.meal_plan' | t
    assign brand_color = '#E85D04'
  elsif request.path contains 'ready-series' or request.path contains 'ready-to-go' or request.path contains 'build-a-box' or request.page_type == 'product'
    assign brand = 'rs'
    assign brand_label = 'brands.ready_series' | t
  endif
%}
{% if section.settings.announcement != blank %}<div class="bg-[#F5B300] text-[#1A1A1A] text-center py-2 px-4 text-[10px] sm:text-[11px] tracking-[0.15em] sm:tracking-[0.2em] uppercase font-semibold">{{ section.settings.announcement }}</div>{% endif %}
<nav class="bg-[#1A1A1A] text-white border-b border-white/10" data-pm-header aria-label="{{ 'navigation.main' | t }}">
  <div class="max-w-[1440px] mx-auto px-4 sm:px-6 h-[56px] sm:h-[60px] flex items-center justify-between gap-4">
    <details class="relative shrink-0" data-brand-switcher><summary class="flex items-center gap-3 hover:opacity-80 transition-opacity group cursor-pointer list-none">
      {% if brand == 'pm' %}{% render 'logos', brand: brand, size: 'sm', variant: 'light' %}{% else %}{% render 'logos', brand: brand, size: 'sm', variant: 'dark' %}{% endif %}
      <span class="hidden sm:flex flex-col items-start leading-none border-l border-white/10 pl-3"><span class="text-[9px] font-mono tracking-[0.3em] uppercase text-white/30 mb-1">{{ 'navigation.current_brand' | t }}</span><span class="flex items-center gap-1.5"><span class="w-1.5 h-1.5 rounded-full shrink-0" style="background:{{ brand_color }}"></span><span class="text-[11px] font-bold tracking-[0.1em] uppercase text-white">{{ brand_label }}</span><svg width="8" height="8" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" class="text-white/35 ml-0.5" aria-hidden="true"><path d="M6 9l6 6 6-6"/></svg></span></span>
    </summary><div class="absolute top-full left-0 mt-3 w-[240px] bg-[#111] border border-white/12 z-50">
      <a href="{{ routes.root_url }}" class="w-full text-left px-4 py-3.5 flex items-center gap-3 hover:bg-white/5 transition-colors border-b border-white/6"><span class="w-[3px] h-6 shrink-0 bg-[#F5B300]"></span><span class="flex-1"><span class="block text-white text-[13px] font-semibold">{{ 'brands.performance_meals' | t }}</span><span class="block text-white/30 text-[10px] mt-0.5">{{ 'brands.parent_description' | t }}</span></span>{% if brand == 'pm' %}<span class="w-1.5 h-1.5 rounded-full bg-[#F5B300]"></span>{% endif %}</a>
      <a href="{{ section.settings.meal_plan_url }}" class="w-full text-left px-4 py-3.5 flex items-center gap-3 hover:bg-white/5 transition-colors border-b border-white/6"><span class="w-[3px] h-6 shrink-0 bg-[#E85D04]"></span><span class="flex-1"><span class="block text-white text-[13px] font-semibold">{{ 'brands.meal_plan' | t }}</span><span class="block text-white/30 text-[10px] mt-0.5">{{ 'brands.meal_plan_description' | t }}</span></span>{% if brand == 'mp' %}<span class="w-1.5 h-1.5 rounded-full bg-[#E85D04]"></span>{% endif %}</a>
      <a href="{{ section.settings.ready_series_url }}" class="w-full text-left px-4 py-3.5 flex items-center gap-3 hover:bg-white/5 transition-colors"><span class="w-[3px] h-6 shrink-0 bg-[#F5B300]"></span><span class="flex-1"><span class="block text-white text-[13px] font-semibold">{{ 'brands.ready_series' | t }}</span><span class="block text-white/30 text-[10px] mt-0.5">{{ 'brands.ready_series_description' | t }}</span></span>{% if brand == 'rs' %}<span class="w-1.5 h-1.5 rounded-full bg-[#F5B300]"></span>{% endif %}</a>
    </div></details>
    <div class="hidden lg:flex items-center gap-6 flex-1 justify-end mr-4"><a href="{{ routes.root_url }}#our-brands" class="text-[11px] tracking-[0.2em] uppercase font-semibold text-white/45 hover:text-white transition-colors">{{ 'navigation.our_brands' | t }}</a><a href="{{ section.settings.about_url }}" class="text-[11px] tracking-[0.2em] uppercase font-semibold text-white/45 hover:text-white transition-colors">{{ 'navigation.about' | t }}</a>{% if section.settings.menu != blank %}{% for link in section.settings.menu.links %}<a href="{{ link.url }}" class="text-[11px] tracking-[0.2em] uppercase font-semibold text-white/45 hover:text-white transition-colors">{{ link.title | escape }}</a>{% endfor %}{% endif %}</div>
    <div class="flex items-center gap-2 sm:gap-3 shrink-0">
      {% if shop.customer_accounts_enabled %}
        {% if customer %}
          {% if customer.metafields.loyalty.points.value != blank %}<a href="{{ routes.account_url }}" class="hidden md:flex items-center gap-1.5 hover:opacity-75 transition-opacity"><span class="text-[15px] leading-none" aria-hidden="true">🪙</span><span class="text-[#F5B300] font-mono text-[11px] font-bold">{{ customer.metafields.loyalty.points.value }} {{ 'account.points' | t }}</span></a>{% endif %}
          <a href="{{ routes.account_url }}" class="flex items-center gap-2 pl-1 pr-2 py-1 border border-white/10 hover:border-white/25 bg-white/5 transition-colors" aria-label="{{ 'account.my_account' | t }}"><span class="w-6 h-6 bg-[#F5B300] rounded-full flex items-center justify-center text-[#111] font-extrabold text-[11px] shrink-0">{{ customer.first_name | default: customer.email | slice: 0 | upcase }}</span><span class="text-white/60 text-[11px] tracking-wide hidden lg:block">{{ customer.first_name | default: customer.email | escape }}</span></a>
        {% else %}
          <a href="{{ routes.account_login_url }}" class="text-white/60 hover:text-white transition-colors text-[11px] tracking-[0.2em] uppercase hidden md:block whitespace-nowrap">{{ 'account.log_in' | t }}</a><a href="{{ routes.account_url }}" class="hidden md:block bg-[#F5B300] text-[#111] text-[10px] font-extrabold tracking-[0.2em] uppercase px-4 py-2 hover:bg-white transition-colors whitespace-nowrap">{{ 'account.sign_up' | t }}</a>
        {% endif %}
      {% endif %}
      <a href="{{ routes.cart_url }}" data-cart-open class="relative text-white/50 hover:text-white transition-colors p-1" aria-label="{{ 'cart.title' | t }}"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M6 2 3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4z"/><path d="M3 6h18M16 10a4 4 0 0 1-8 0"/></svg><span data-cart-count class="absolute -top-2 -right-2 bg-[#F5B300] text-[#1A1A1A] text-[9px] font-bold rounded-full w-[17px] h-[17px] flex items-center justify-center" {% if cart.item_count == 0 %}hidden{% endif %}>{{ cart.item_count }}</span></a>
      <button type="button" data-mobile-toggle class="lg:hidden text-white/70 hover:text-white transition-colors p-1" aria-label="{{ 'navigation.menu' | t }}" aria-expanded="false" aria-controls="MobileMenu-{{ section.id }}"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true" data-menu-icon><path d="M3 6h18M3 12h18M3 18h18"/></svg><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true" data-close-icon hidden><path d="M18 6 6 18M6 6l12 12"/></svg></button>
    </div>
  </div>
  <div class="lg:hidden bg-[#111] border-t border-white/10 overflow-y-auto max-h-[80vh]" id="MobileMenu-{{ section.id }}" data-mobile-menu hidden><div class="px-5 py-4 space-y-1">
    <p class="text-[9px] font-mono tracking-[0.4em] text-white/30 uppercase py-2">{{ 'navigation.switch_brand' | t }}</p>
    <a href="{{ routes.root_url }}" class="w-full text-left py-3 px-3 flex items-center gap-3 text-[15px] hover:bg-white/5 transition-colors border-b border-white/5 text-white/60"><span class="w-[3px] h-5 shrink-0 bg-[#F5B300]"></span>{{ 'brands.performance_meals' | t }}{% if brand == 'pm' %}<span class="ml-auto text-[9px] font-mono tracking-widest uppercase text-white/30">{{ 'navigation.current' | t }}</span>{% endif %}</a>
    <a href="{{ section.settings.meal_plan_url }}" class="w-full text-left py-3 px-3 flex items-center gap-3 text-[15px] hover:bg-white/5 transition-colors border-b border-white/5 text-white/60"><span class="w-[3px] h-5 shrink-0 bg-[#E85D04]"></span>{{ 'brands.meal_plan' | t }}{% if brand == 'mp' %}<span class="ml-auto text-[9px] font-mono tracking-widest uppercase text-white/30">{{ 'navigation.current' | t }}</span>{% endif %}</a>
    <a href="{{ section.settings.ready_series_url }}" class="w-full text-left py-3 px-3 flex items-center gap-3 text-[15px] hover:bg-white/5 transition-colors border-b border-white/5 text-white/60"><span class="w-[3px] h-5 shrink-0 bg-[#F5B300]"></span>{{ 'brands.ready_series' | t }}{% if brand == 'rs' %}<span class="ml-auto text-[9px] font-mono tracking-widest uppercase text-white/30">{{ 'navigation.current' | t }}</span>{% endif %}</a>
    <p class="text-[9px] font-mono tracking-[0.4em] text-white/30 uppercase py-2 mt-2">{{ 'navigation.more' | t }}</p><a href="{{ routes.root_url }}#our-brands" class="block w-full text-left py-3 px-3 text-[15px] text-white/70 hover:text-white hover:bg-white/5 transition-colors border-b border-white/5">{{ 'navigation.our_brands' | t }}</a><a href="{{ section.settings.about_url }}" class="block w-full text-left py-3 px-3 text-[15px] text-white/70 hover:text-white hover:bg-white/5 transition-colors border-b border-white/5">{{ 'navigation.about' | t }}</a>{% if section.settings.menu != blank %}{% for link in section.settings.menu.links %}<a href="{{ link.url }}" class="block w-full text-left py-3 px-3 text-[15px] text-white/70 hover:text-white hover:bg-white/5 transition-colors border-b border-white/5">{{ link.title | escape }}</a>{% endfor %}{% endif %}
    {% if shop.customer_accounts_enabled %}<p class="text-[9px] font-mono tracking-[0.4em] text-white/30 uppercase py-2 mt-2">{{ 'account.title' | t }}</p>
      {% if customer %}<div class="flex items-center gap-3 px-3 py-3 border-b border-white/5"><span class="w-9 h-9 bg-[#F5B300] rounded-full flex items-center justify-center text-[#111] font-extrabold text-[13px]">{{ customer.first_name | default: customer.email | slice: 0 | upcase }}</span><span class="text-white text-[14px] font-semibold">{{ customer.name | escape }}</span></div><a href="{{ routes.account_url }}" class="block w-full text-left py-3 px-3 text-[15px] text-white/70 hover:text-white hover:bg-white/5 transition-colors border-b border-white/5">{{ 'account.my_account' | t }}</a><a href="{{ routes.account_logout_url }}" class="block w-full text-left py-3 px-3 text-[15px] text-white/70 hover:text-white hover:bg-white/5 transition-colors border-b border-white/5">{{ 'account.log_out' | t }}</a>
      {% else %}<div class="flex gap-3 px-3 py-4 border-b border-white/5"><a href="{{ routes.account_login_url }}" class="flex-1 text-center border border-white/20 text-white py-3 text-[13px] font-bold tracking-widest uppercase hover:bg-white/10 transition-colors">{{ 'account.log_in' | t }}</a><a href="{{ routes.account_url }}" class="flex-1 text-center bg-[#F5B300] text-[#111] py-3 text-[13px] font-extrabold tracking-widest uppercase hover:bg-white transition-colors">{{ 'account.sign_up' | t }}</a></div>{% endif %}
    {% endif %}
  </div></div>
</nav>
{% stylesheet %}
.pm-header-section{position:sticky;top:0;z-index:50}[data-brand-switcher] summary::-webkit-details-marker{display:none}[data-brand-switcher][open] summary svg{transform:rotate(180deg)}
{% endstylesheet %}
''',[field('announcement',None,type='inline_richtext',label='Announcement (enable only after discount and delivery rules are configured)'),field('meal_plan_url','/pages/meal-plan',type='url'),field('ready_series_url','/collections/ready-series',type='url'),field('about_url','/pages/about',type='url'),field('menu',None,type='link_list',label='Additional menu')]).replace('"settings": [','"class": "pm-header-section",\n  "settings": [',1))

write(Path('sections/footer.liquid'),section('Performance Meals footer',r'''
<footer class="bg-[#1A1A1A] border-t border-white/5">
  <div class="max-w-[1440px] mx-auto px-6 py-10 flex flex-col md:flex-row items-start md:items-center justify-between gap-8"><a href="{{ routes.root_url }}" class="shrink-0">{% render 'logos', brand: 'pm', size: 'sm', variant: 'light' %}</a>
    <nav class="flex flex-wrap gap-x-7 gap-y-2" aria-label="{{ 'navigation.footer' | t }}"><a href="{{ section.settings.ready_series_url }}" class="text-[11px] sm:text-[12px] text-white/60 hover:text-[#F5B300] transition-colors tracking-wide whitespace-nowrap">{{ 'brands.ready_series' | t }}</a><a href="{{ section.settings.meal_plan_url }}" class="text-[11px] sm:text-[12px] text-white/60 hover:text-[#F5B300] transition-colors tracking-wide whitespace-nowrap">{{ 'brands.meal_plan' | t }}</a><a href="{{ section.settings.about_url }}" class="text-[11px] sm:text-[12px] text-white/60 hover:text-[#F5B300] transition-colors tracking-wide whitespace-nowrap">{{ 'navigation.about' | t }}</a>{% if section.settings.menu != blank %}{% for link in section.settings.menu.links %}<a href="{{ link.url }}" class="text-[11px] sm:text-[12px] text-white/60 hover:text-[#F5B300] transition-colors tracking-wide whitespace-nowrap">{{ link.title | escape }}</a>{% endfor %}{% endif %}</nav>
    {% if section.settings.email != blank or section.settings.contact != blank %}<div class="text-[11px] text-white/30 text-right shrink-0 hidden lg:block">{% if section.settings.email != blank %}<a href="mailto:{{ section.settings.email | escape }}">{{ section.settings.email | escape }}</a>{% endif %}<div class="mt-0.5">{{ section.settings.contact | escape }}</div></div>{% endif %}
  </div>
  <div class="border-t border-white/5"><div class="max-w-[1440px] mx-auto px-6 py-4 flex flex-col sm:flex-row items-center justify-between gap-3 text-[11px] text-white/30"><span>© {{ 'now' | date: '%Y' }} {{ section.settings.company_name | default: shop.name | escape }}{% if section.settings.registration != blank %} · {{ section.settings.registration | escape }}{% endif %}</span><div class="flex gap-5 items-center">{% for policy in shop.policies %}{% if policy != blank %}<a href="{{ policy.url }}" class="hover:text-white/70 transition-colors">{{ policy.title | escape }}</a>{% endif %}{% endfor %}</div></div></div>
</footer>
''',[field('ready_series_url','/collections/ready-series',type='url'),field('meal_plan_url','/pages/meal-plan',type='url'),field('about_url','/pages/about',type='url'),field('menu',None,type='link_list',label='Additional footer menu'),field('email',None),field('contact',None,label='Verified phone and location'),field('company_name','Performance Meals Pte. Ltd.'),field('registration',None,label='Verified company registration')]))

promo_markup=r'''
{% if section.settings.enabled or request.design_mode %}
<dialog class="pm-promo-dialog p-0 overflow-hidden" data-promo-popup data-enabled="{{ section.settings.enabled }}" data-delay="{{ section.settings.delay }}" data-section-id="{{ section.id }}" aria-labelledby="PromoHeading-{{ section.id }}">
  <div class="relative flex flex-col overflow-hidden" style="background:#191919;border:1px solid #f5b800;width:min(560px,96vw)">
    <div class="flex items-center justify-between px-5 py-3.5"><span class="font-bold text-[#f5b800] text-[10px] tracking-[0.1em] uppercase">{{ section.settings.eyebrow | escape }}</span><button type="button" data-promo-close class="text-white/50 hover:text-white transition-colors p-1" aria-label="{{ 'general.close' | t }}"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="M18 6 6 18M6 6l12 12"/></svg></button></div>
    <div class="flex" style="height:42px" role="tablist" aria-label="{{ 'promo.offers' | t }}"><button type="button" role="tab" id="PromoTab-{{ section.id }}" data-promo-tab="promo" aria-selected="true" aria-controls="PromoPanel-{{ section.id }}" class="pm-promo-tab flex flex-1 items-center justify-center font-bold text-[11px] tracking-[0.06em] transition-colors">{{ 'promo.promotional_offer' | t }}</button><button type="button" role="tab" id="SubTab-{{ section.id }}" data-promo-tab="sub" aria-selected="false" aria-controls="SubPanel-{{ section.id }}" tabindex="-1" class="pm-promo-tab flex flex-1 items-center justify-center font-bold text-[11px] tracking-[0.06em] transition-colors">{{ 'promo.subscription_deal' | t }}</button></div>
    <div class="flex flex-col gap-4 p-6" role="tabpanel" id="PromoPanel-{{ section.id }}" aria-labelledby="PromoTab-{{ section.id }}" data-promo-panel="promo">
      <h2 id="PromoHeading-{{ section.id }}" class="font-bold leading-[1.05] text-white font-display" style="font-size:clamp(22px,3.5vw,32px)">{{ section.settings.heading | escape }}</h2><p class="text-[#d6d4ce] text-[13px] leading-[1.5]">{{ section.settings.body | escape }}</p>
      {% if section.settings.code != blank %}<div class="bg-white flex items-center justify-between px-4" style="height:56px"><div class="flex flex-col gap-0.5"><span class="font-bold text-[#6c6a66] text-[9px] tracking-[0.1em]">{{ 'promo.code' | t }}</span><span class="font-bold text-black text-[20px] leading-none font-display">{{ section.settings.code | escape }}</span></div><button type="button" data-copy-code="{{ section.settings.code | escape }}" data-copy-label="{{ 'promo.copy' | t }}" data-copied-label="{{ 'promo.copied' | t }}" class="flex items-center gap-2 font-bold text-[#191919] text-[12px] hover:opacity-80 transition-opacity" style="background:#f5b800;height:38px;padding:0 16px">{{ 'promo.copy' | t }} →</button></div>{% endif %}
      {% if section.settings.terms != blank %}<p class="text-[#b9b7b0] text-[10px] leading-[1.5]">{{ section.settings.terms | escape }}</p>{% endif %}<a href="{{ section.settings.url }}" class="flex items-center justify-center gap-2 w-full font-bold text-[#191919] text-[12px] hover:opacity-85 transition-opacity" style="background:#f5b800;height:42px">{{ section.settings.label | escape }} →</a>
    </div>
    <div class="flex flex-col gap-4 p-6" role="tabpanel" id="SubPanel-{{ section.id }}" aria-labelledby="SubTab-{{ section.id }}" data-promo-panel="sub" hidden>
      <div class="flex flex-col gap-1.5"><h3 class="font-bold text-white leading-tight font-display" style="font-size:clamp(18px,2.5vw,26px)">{{ section.settings.subscription_heading | escape }}</h3><p class="text-[#d6d4ce] text-[12px] leading-[1.5]">{{ section.settings.subscription_body | escape }}</p></div>
      <div class="grid grid-cols-1 sm:grid-cols-2 gap-3">{% for block in section.blocks %}{% if block.type == '@app' %}{% render block %}{% elsif block.settings.product != blank %}{% assign offer_product = block.settings.product %}<div class="flex flex-col justify-between p-4" style="background:{% if block.settings.featured %}#fff3cc{% else %}#fff{% endif %};border:1px solid #d8d6d0" {{ block.shopify_attributes }}><div class="flex flex-col gap-1.5 mb-4">{% if block.settings.featured %}<span class="font-bold text-[#b48000] text-[9px] tracking-[0.08em] uppercase">{{ 'promo.most_popular' | t }}</span>{% endif %}<p class="font-bold text-black text-[18px] leading-tight font-display">{{ offer_product.title | escape }}</p><p class="text-[#6c6a66] text-[11px]">{{ block.settings.description | escape }}</p><p class="font-bold text-black text-[17px] font-display">{{ offer_product.price | money }}</p><p class="font-bold text-[#187a4d] text-[11px]">{{ block.settings.savings | escape }}</p></div><a href="{{ offer_product.url }}" class="flex items-center justify-center gap-2 w-full font-bold text-[#191919] text-[12px] hover:opacity-85 transition-opacity" style="background:#f5b800;min-height:38px">{{ 'promo.select' | t: product: offer_product.title }} →</a></div>{% endif %}{% endfor %}</div>
      {% if section.settings.subscription_note != blank %}<p class="text-[#b9b7b0] text-[10px] text-center">{{ section.settings.subscription_note | escape }}</p>{% endif %}
    </div>
  </div>
</dialog>
{% endif %}
{% stylesheet %}
.pm-promo-dialog{margin:auto;border:0;max-width:96vw;max-height:90vh;color:#fff;background:#191919}.pm-promo-dialog::backdrop{background:#000b}.pm-promo-tab{background:#242424;color:#fff}.pm-promo-tab[aria-selected=true]{background:#f5b800;color:#191919;border-bottom:2px solid #f5b800}
{% endstylesheet %}
'''
write(Path('sections/promo-popup.liquid'),section('Promotion popup',promo_markup,[field('enabled',False,type='checkbox',label='Enable after configuring real offers in Shopify'),field('delay',5,type='range',label='Delay (seconds)',min=1,max=30,step=1),field('eyebrow','THIS WEEK ONLY'),field('heading','20% OFF THE MEALS THAT KEEP UP.'),field('body',"Save on selected Ready Series meals. Stock the freezer once and move through Singapore's busiest days without missing dinner.",type='textarea'),field('code',None,label='Active Shopify discount code'),field('terms',None,type='textarea',label='Verified offer expiry and terms'),field('url','/collections/ready-series',type='url'),field('label','Shop selected meals'),field('subscription_heading','SET THE FREEZER. SAVE EVERY CYCLE.'),field('subscription_body','Choose a package. Pause, skip or cancel anytime.',type='textarea'),field('subscription_note',None,type='textarea')],[{'type':'offer','name':'Subscription product','settings':[field('product',None,type='product'),field('description',None),field('savings',None,label='Verified savings'),field('featured',False,type='checkbox')]},{'type':'@app'}],3))

